def stub(fid, wall_pt, pt, zf, h, serves, note='', tee=None):
    """ท่อแยก 1/2 นิ้ว: จากท่อประธานใต้ดินข้างคาน → (ลอดใต้คานถ้าสุขภัณฑ์อยู่อีกฝั่ง) → ขึ้นข้างคานฝั่งสุขภัณฑ์ โผล่เหนือหลังคาน → หักเข้าผนัง → ขึ้นในผนังถึงระดับจุดจ่ายน้ำ → ออกที่ผิวผนัง
    tee = ระดับที่แยกจากท่อในผนังของสุขภัณฑ์อีกฝั่งผนัง (ใช้ท่อขึ้นร่วมกัน)"""
    ax, cw, cb, mn = next(w for w in WALLS if abs(wall_pt[0 if w[0] == 'x' else 1] - w[1]) < 1e-6)
    k = 0 if ax == 'x' else 1; u = wall_pt[1 - k]; zp = zf + h
    P2 = lambda c: (c, u) if k == 0 else (u, c)
    sf = 1 if pt[k] > cw else -1; face = cw + 0.05 * sf
    if tee is not None:
        pts = [tee] + ([(*P2(cw), tee[2])] if (round(tee[0], 3), round(tee[1], 3)) != tuple(round(c, 3) for c in P2(cw)) else []) + ([(*P2(cw), zp)] if abs(tee[2] - zp) > 1e-6 else []) + [(*P2(face), zp)]
    else:
        rise = mn if (mn > cb) == (sf > 0) else cb + 0.16 * sf; ztop = max(zf + 0.05, 0.25)   # โผล่เหนือหลังคานคอดิน (+0.20)
        pts = [(*P2(mn), ZG)] + ([(*P2(rise), ZG)] if abs(rise - mn) > 1e-6 else []) + [(*P2(rise), ztop), (*P2(cw), ztop), (*P2(cw), zp), (*P2(face), zp)]
    Pp('CW-' + fid, 'cw', '1/2"', pts, serves, NW + (' · ' + note if note else ''))
    for f in fx:
        if f['id'] == fid and f['type'] in ('WC', 'LAV1', 'LAV2'): f['supply_z'] = round(zp, 3)
